import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

depthwise_conv2d_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void depthwise_conv2d_kernel(
    const float *input,
    const float *weight,
    const float *bias,
    float *output,
    int B, int C, int H, int W,
    int kernel_size, int stride, int padding,
    bool has_bias)
{
    int H_out = (H + 2 * padding - kernel_size) / stride + 1;
    int W_out = (W + 2 * padding - kernel_size) / stride + 1;

    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int num_output_elements = B * C * H_out * W_out;
    if (index >= num_output_elements) return;

    int w_out_i = index % W_out;
    int h_out_i = (index / W_out) % H_out;
    int c_i = (index / (W_out * H_out)) % C;
    int b_i = index / (W_out * H_out * C);

    float sum_val = 0.0f;

    int h_in_start = h_out_i * stride - padding;
    int w_in_start = w_out_i * stride - padding;

    int input_offset = (b_i * C + c_i) * (H * W);
    int weight_offset = c_i * kernel_size * kernel_size;

    for(int kh = 0; kh < kernel_size; kh++){
        for(int kw = 0; kw < kernel_size; kw++){
            int h_in = h_in_start + kh;
            int w_in = w_in_start + kw;
            if(h_in >= 0 && h_in < H && w_in >= 0 && w_in < W){
                float val = input[input_offset + h_in * W + w_in];
                float w_val = weight[weight_offset + kh * kernel_size + kw];
                sum_val += val * w_val;
            }
        }
    }

    if(has_bias){
        sum_val += bias[c_i];
    }
    output[index] = sum_val;
}

torch::Tensor depthwise_conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding)
{
    int B = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    int kernel_size = weight.size(2);
    bool has_bias = bias.defined() && bias.numel() > 0;

    int H_out = (H + 2 * padding - kernel_size) / stride + 1;
    int W_out = (W + 2 * padding - kernel_size) / stride + 1;

    auto output = torch::zeros({B, C, H_out, W_out}, input.options());

    int num_output_elements = B * C * H_out * W_out;
    int block_size = 256;
    int num_blocks = (num_output_elements + block_size - 1) / block_size;

    depthwise_conv2d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        has_bias ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        B, C, H, W,
        kernel_size, stride, padding, has_bias
    );

    return output;
}
""".strip()

depthwise_conv2d_cpp_source = r"""
torch::Tensor depthwise_conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding);
""".strip()

depthwise_conv2d = load_inline(
    name="depthwise_conv2d",
    cpp_sources=depthwise_conv2d_cpp_source,
    cuda_sources=depthwise_conv2d_source,
    functions=["depthwise_conv2d_forward"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized depthwise 2D convolution using a custom CUDA kernel.
    """
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, bias: bool = False):
        super(ModelNew, self).__init__()
        self.weight = nn.Parameter(torch.randn(in_channels, 1, kernel_size, kernel_size))
        self.bias = nn.Parameter(torch.randn(in_channels)) if bias else None
        self.stride = stride
        self.padding = padding

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self.bias is not None:
            return depthwise_conv2d.depthwise_conv2d_forward(
                x, self.weight, self.bias, self.stride, self.padding
            )
        else:
            return depthwise_conv2d.depthwise_conv2d_forward(
                x, self.weight, torch.tensor([], device=x.device), self.stride, self.padding
            )
